CREATE OR REPLACE FUNCTION public.admin_delete_merchant_featured_slot_v2(p_admin_id uuid, p_id uuid)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
declare
  v_deleted uuid;
begin
  -- السماح للأدمن المخوّل فقط
  if p_admin_id is null
     or not public.meshwar_is_admin(p_admin_id) then
    raise exception 'not authorized';
  end if;

  -- يجب إرسال معرف الحملة
  if p_id is null then
    raise exception 'campaign id is required';
  end if;

  -- الحذف محصور حصرياً بجدول الحملات
  delete from public.merchant_featured_slots
  where id = p_id
  returning id into v_deleted;

  -- حماية من محاولة حذف حملة غير موجودة
  if v_deleted is null then
    raise exception 'campaign not found';
  end if;

  return true;
end;
$function$

CREATE OR REPLACE FUNCTION public.admin_toggle_merchant_featured_slot(p_admin_id uuid, p_id uuid, p_is_active boolean)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public'
AS $function$
BEGIN
    IF NOT public.meshwar_is_admin(p_admin_id) THEN
        RAISE EXCEPTION 'not authorized';
    END IF;

    UPDATE public.merchant_featured_slots
    SET is_active = p_is_active
    WHERE id = p_id;

    IF NOT FOUND THEN
        RAISE EXCEPTION 'campaign not found';
    END IF;

    RETURN true;
END;
$function$
